            report={'schema':1,'run_id':plan['run_id'],'server_uuid':plan['server_uuid'],'plan_sha256':t.digest(plan),'source_epoch':profile['source_epoch'],'completed_units':len(records),'record_sha256':hashes,'comparison_rows':len(rows),'comparison_logical_sha256':t.digest(rows),'statement':'fresh_equal_single_column_histograms_do_not_determine_joint_cardinality','status':'verified'}
            file=directory/'report.json'
            if file.exists()and t.canonical(t.read_json(file))!=t.canonical(report):raise ValueError('existing strict report metadata differs')
            if comparison.exists():
                existing=load_comparison(comparison);indexed={}
                for row in existing:
                    key=(row['case_id'],row['world'],row['kind'])
                    if key in indexed:raise ValueError('duplicate comparison cell')
                    indexed[key]=row
                keys=[(row['case_id'],row['world'],row['kind'])for row in rows]
                if set(indexed)!=set(keys)or t.canonical([indexed[key]for key in keys])!=t.canonical(rows):raise ValueError('existing numerical comparison differs')
            else:t.publish_raw(comparison,t.csv_bytes(HEADERS,[[row[key]for key in HEADERS]for row in rows]))
            if not file.exists():t.publish(file,report)
            return report
    finally:connection.close()
